div.script:
function toggleStockField() {
    var typeSelect = document.getElementById('type');
    var stockGroup = document.getElementById('stock_group');
    var stockInput = document.getElementById('stock_qty');
    if (typeSelect.value === 'product') {
        stockGroup.style.display = 'block';
        stockInput.setAttribute('required', '1');
    } else {
        stockGroup.style.display = 'none';
        stockInput.removeAttribute('required');
        stockInput.value = '';
    }
}

// ── Conectar Clics en Slots de Foto ──
document.addEventListener('DOMContentLoaded', function() {
    toggleStockField();
    for (var i = 1; i <= 4; i++) {
        (function(slotNum) {
            var card = document.getElementById('slot_card_' + slotNum);
            var fileInput = document.getElementById('file_slot_' + slotNum);
            if (card && fileInput) {
                card.addEventListener('click', function(e) {
                    if (e.target.closest('button')) return;
                    fileInput.click();
                });
            }
        })(i);
    }
    updatePhotoCounter();
});

// ── Motor de Compresión Inteligente Client-Side (1200x1200px, Web/Mobile friendly) ──
function handlePhotoSelect(slotNum, input) {
    if (!input.files || !input.files[0]) return;
    var file = input.files[0];

    // Validar tipo de archivo
    if (!file.type.match(/^image\//)) {
        alert('Por favor selecciona un archivo de imagen válido (JPG, PNG o WEBP).');
        input.value = '';
        return;
    }

    var toast = document.getElementById('compression_toast');
    if (toast) toast.classList.remove('d-none');

    var reader = new FileReader();
    reader.onload = function(e) {
        var img = new Image();
        img.onload = function() {
            // Dimensionamiento óptimo estilo Mercado Libre: Max 1200x1200px
            var maxDim = 1200;
            var width = img.width;
            var height = img.height;

            if (width > maxDim || height > maxDim) {
                if (width > height) {
                    height = Math.round((height * maxDim) / width);
                    width = maxDim;
                } else {
                    width = Math.round((width * maxDim) / height);
                    maxDim = height;
                }
            }

            // Render en Canvas y compresión JPEG 85%
            var canvas = document.createElement('canvas');
            canvas.width = width;
            canvas.height = height;
            var ctx = canvas.getContext('2d');

            // Fondo blanco para imágenes transparentes PNG
            ctx.fillStyle = '#FFFFFF';
            ctx.fillRect(0, 0, width, height);
            ctx.drawImage(img, 0, 0, width, height);

            var compressedBase64 = canvas.toDataURL('image/jpeg', 0.85);

            // Actualizar Preview y Campo Hidden
            var preview = document.getElementById('preview_slot_' + slotNum);
            var b64Field = document.getElementById('b64_slot_' + slotNum);
            var emptyState = document.getElementById('empty_slot_' + slotNum);
            var filledState = document.getElementById('filled_slot_' + slotNum);
            var card = document.getElementById('slot_card_' + slotNum);

            if (preview) preview.src = compressedBase64;
            if (b64Field) b64Field.value = compressedBase64;
            if (emptyState) emptyState.classList.add('d-none');
            if (filledState) filledState.classList.remove('d-none');
            if (card) {
                card.style.border = '2px solid #28a745 !important';
                card.style.backgroundColor = '#ffffff';
            }

            if (toast) toast.classList.add('d-none');
            updatePhotoCounter();
        };
        img.src = e.target.result;
    };
    reader.readAsDataURL(file);
}

function removePhoto(slotNum, ev) {
    if (ev) { ev.preventDefault(); ev.stopPropagation(); }
    var fileInput = document.getElementById('file_slot_' + slotNum);
    var b64Field = document.getElementById('b64_slot_' + slotNum);
    var emptyState = document.getElementById('empty_slot_' + slotNum);
    var filledState = document.getElementById('filled_slot_' + slotNum);
    var card = document.getElementById('slot_card_' + slotNum);

    if (fileInput) fileInput.value = '';
    if (b64Field) b64Field.value = '__REMOVE__';
    if (emptyState) emptyState.classList.remove('d-none');
    if (filledState) filledState.classList.add('d-none');
    if (card) {
        card.style.border = '2px dashed #ced4da !important';
        card.style.backgroundColor = '#fafafa';
    }
    updatePhotoCounter();
}

function updatePhotoCounter() {
    var count = 0;
    for (var i = 1; i <= 4; i++) {
        var filled = document.getElementById('filled_slot_' + i);
        var empty = document.getElementById('empty_slot_' + i);
        if (filled && !filled.classList.contains('d-none')) {
            count++;
        } else if (empty && empty.querySelector('img')) {
            count++;
        }
    }
    var counterEl = document.getElementById('photos_counter');
    if (counterEl) {
        counterEl.textContent = count + ' de 4 fotos cargadas';
        if (count > 0) {
            counterEl.className = 'badge badge-success text-white px-2 py-1';
        } else {
            counterEl.className = 'badge badge-light border text-muted px-2 py-1';
        }
    }
}
